            if(Files.exists(out,LinkOption.NOFOLLOW_LINKS))throw new IOException("Output must be NEW; existing output is retained unchanged");
            NextflowFiles.directory(out.getParent());for(Path p:List.of(runtime,resources,targets,list))if(p.startsWith(out)||out.startsWith(p))throw new IOException("Inputs/provider and owned output may not overlap");
