            capture(resources.resolve("ncbi.map"),bundle,"inputs/resources/ncbi.map",caps,pins,origins);capture(resources.resolve("ncbi.tre"),bundle,"inputs/resources/ncbi.tre",caps,pins,origins);
            capture(targets,bundle,"inputs/targets.txt",caps,pins,origins);capture(list,bundle,"inputs/rma-list.tsv",caps,pins,origins);
            var samples=sampleList(list,caps);for(var sample:samples.entrySet()){if(sample.getValue().startsWith(out)||out.startsWith(sample.getValue()))throw new IOException("RMA input overlaps owned output");capture(sample.getValue(),bundle,"inputs/rma/"+sample.getKey()+".rma6",caps,pins,origins);}
