            var report=new LinkedHashMap<String,Object>();report.put("status",STATUS);report.put("profile",profile);report.put("input_provenance",provenance);report.put("runtime_inventory_sha256",RUNTIME);report.put("capacities",caps.document());report.put("producer_root",producer);report.put("runtime_root",runtime.toString());report.put("input_pins",pins);report.put("original_bindings",origins);report.put("sample_labels",samples.keySet());report.put("selection",data.document());report.put("output_audit",output);report.put("process_exit",0);report.put("owned_live_after_cleanup",List.of());report.put("new_tool_credit",0);report.put("whole_tool_qualified",false);report.put("producer_authenticated",false);
