        for(String label:new TreeSet<>(labels)){var rows=new ArrayList<MaltExtractRmaReader.Read>();var report=MaltExtractRmaReader.read(runtime,input.resolve("rma/"+label+".rma6"),caps.reader(),MaltExtractRmaReader.EXTRACTION,rows::add);reads.put(label,rows);reports.put(label,report);keys.addAll(report.classifications().keySet());}
