        try(var paths=Files.walk(original)){for(Path p:paths.filter(p->!Files.isDirectory(p,LinkOption.NOFOLLOW_LINKS)).sorted().toList()){if(index.size()>=100000)throw new IOException("Complete original output file capacity exceeded");String name=sourceName(original.relativize(p).toString());var before=NextflowFiles.pin(p,caps.fileBytes(),()->{});String member=String.format(Locale.ROOT,"outputs/%06d.bin",index.size()+1);Files.copy(p,bundle.resolve(member));if(!NextflowFiles.pin(bundle.resolve(member),caps.fileBytes(),()->{}).equals(before)||!NextflowFiles.pin(p,caps.fileBytes(),()->{}).equals(before))throw new IOException("Original output changed during complete capture");index.put(name,Map.of("member",member,"bytes",before.bytes(),"sha256",before.sha256()));}}
