    private static void severe(MaltExtractOutputAudit.View view,Path stderr)throws IOException {
        for(String name:view.members())if(name.equals("error.txt")||name.startsWith("log.txt"))try(var r=view.reader(name)){severe(r,name);}
        try(var r=Files.newBufferedReader(stderr,StandardCharsets.UTF_8)){severe(r,"process.stderr");}
    }
    private static void severe(BufferedReader reader,String name)throws IOException {for(String line;(line=reader.readLine())!=null;)if(line.contains("SEVERE")||line.contains("Exception in thread")||line.contains("OutOfMemoryError"))throw new IOException("Original logged a fatal error despite possible zero exit: "+name+" / "+line);}
    private static Map<String,NextflowFiles.Pin> inventory(Path root,long maximum)throws IOException {var result=new TreeMap<String,NextflowFiles.Pin>();try(var paths=Files.walk(root)){for(Path p:paths.filter(p->!Files.isDirectory(p,LinkOption.NOFOLLOW_LINKS)).toList()){if(result.size()>=100000)throw new IOException("Complete portable bundle exceeds member capacity");String name=NextflowFiles.member(root.relativize(p).toString().replace('\\','/'));if(!name.equals("COMPONENT_COMPLETED.json"))result.put(name,NextflowFiles.pin(p,maximum,()->{}));}}return result;}
    private static void same(Object expected,Object actual,String cause)throws IOException {if(!NextflowJson.json(expected).equals(NextflowJson.json(actual)))throw new IOException(cause);}
    private static void verify(Path bundle,Path runtime)throws IOException {
        NextflowFiles.directory(bundle);if(Files.exists(bundle.resolve("FAILURE.json"))||Files.exists(bundle.resolve("WARNINGS_FAILURE.md"))||Files.exists(bundle.getParent().resolve("FAILURE.json")))throw new IOException("Failed/provisional original workflow cannot be admitted");
        var complete=NextflowFiles.object(NextflowFiles.json(bundle.resolve("COMPONENT_COMPLETED.json"),67108864));NextflowFiles.keys(complete,"status","files","new_tool_credit");var report=NextflowFiles.object(NextflowFiles.json(bundle.resolve("audit.json"),67108864));
        NextflowFiles.keys(report,"status","profile","input_provenance","runtime_inventory_sha256","capacities","producer_root","runtime_root","input_pins","original_bindings","sample_labels","selection","output_audit","process_exit","owned_live_after_cleanup","new_tool_credit","whole_tool_qualified","producer_authenticated");
        if(!STATUS.equals(complete.get("status"))||NextflowFiles.integer(complete.get("new_tool_credit"),0,0)!=0||!STATUS.equals(report.get("status"))||!RUNTIME.equals(report.get("runtime_inventory_sha256"))||!Boolean.FALSE.equals(report.get("whole_tool_qualified"))||!Boolean.FALSE.equals(report.get("producer_authenticated"))||NextflowFiles.integer(report.get("new_tool_credit"),0,0)!=0||NextflowFiles.integer(report.get("process_exit"),0,0)!=0||!NextflowFiles.list(report.get("owned_live_after_cleanup")).isEmpty())throw new IOException("Unsupported saved workflow scope, runtime or process claim");
        String profile=profile(NextflowFiles.text(report.get("profile")));if(!Set.of("supplied","native-accession-alternative").contains(report.get("input_provenance")))throw new IOException("Invalid saved input provenance");Caps caps=caps(NextflowFiles.object(report.get("capacities")),true);
        var expected=new TreeMap<String,NextflowFiles.Pin>();for(var entry:NextflowFiles.object(complete.get("files")).entrySet())expected.put(NextflowFiles.member(NextflowFiles.text(entry.getKey())),NextflowFiles.fingerprint(entry.getValue(),caps.fileBytes()));same(expected,inventory(bundle,caps.fileBytes()),"Complete portable bundle inventory differs");
        var pins=new TreeMap<String,NextflowFiles.Pin>();for(var entry:NextflowFiles.object(report.get("input_pins")).entrySet())pins.put(NextflowFiles.member(NextflowFiles.text(entry.getKey())),NextflowFiles.fingerprint(entry.getValue(),caps.fileBytes()));var actualInputs=new TreeMap<String,NextflowFiles.Pin>();expected.forEach((n,p)->{if(n.startsWith("inputs/"))actualInputs.put(n,p);});if(!pins.equals(actualInputs))throw new IOException("Complete captured input binding differs");checkInputBytes(pins,caps);
        var labels=new TreeSet<String>();for(Object value:NextflowFiles.list(report.get("sample_labels"))){String label=NextflowFiles.text(value);if(!label.matches("[A-Za-z][A-Za-z0-9_-]{0,63}")||!labels.add(label))throw new IOException("Invalid/duplicate saved sample label");}if(labels.isEmpty()||labels.size()>caps.samples())throw new IOException("Complete saved sample capacity exceeded");
        var requiredInputs=new TreeSet<>(Set.of("inputs/resources/ncbi.map","inputs/resources/ncbi.tre","inputs/targets.txt","inputs/rma-list.tsv"));for(String label:labels)requiredInputs.add("inputs/rma/"+label+".rma6");if(!pins.keySet().equals(requiredInputs))throw new IOException("Saved sample list omits/adds captured complete RMA inputs");
        var origins=NextflowFiles.object(report.get("original_bindings"));if(!origins.keySet().equals(requiredInputs))throw new IOException("Original input provenance bindings differ");
        var listed=NextflowFiles.utf8(NextflowFiles.bytes(bundle.resolve("inputs/rma-list.tsv"),16777216)).lines().toList();if(listed.size()!=labels.size()+1||!listed.get(0).equals("sample_id\trma6"))throw new IOException("Captured complete RMA list differs");var listedLabels=new TreeSet<String>();for(String row:listed.subList(1,listed.size())){String[] f=row.split("\t",-1);if(f.length!=2||f[1].isEmpty()||!listedLabels.add(f[0]))throw new IOException("Malformed captured original RMA list");}if(!listedLabels.equals(labels))throw new IOException("Captured original list/sample labels differ");
        String producer=NextflowFiles.text(report.get("producer_root")),provider=NextflowFiles.text(report.get("runtime_root"));if(!producer.startsWith("/")||producer.endsWith("/")||!provider.startsWith("/")||provider.endsWith("/"))throw new IOException("Invalid saved canonical Linux producer/provider path");
        var invocation=NextflowFiles.object(NextflowFiles.json(bundle.resolve("invocation.json"),16777216));same(Map.of("command",command(producer,provider,labels,profile,caps),"environment",environment(provider),"producer_root",producer,"runtime_root",provider,"process_limits",caps.process()),invocation,"Saved invocation/profile/environment differs");
        var process=NextflowFiles.object(NextflowFiles.json(bundle.resolve("process/process.json"),16777216));var hard=new ArrayList<>(List.of("/usr/bin/setsid","/usr/bin/prlimit","--as="+caps.process().addressSpaceBytes(),"--cpu="+caps.process().cpuSeconds(),"--fsize="+caps.process().fileBytes(),"--nofile="+caps.process().openFiles(),"--"));hard.addAll(command(producer,provider,labels,profile,caps));same(hard,process.get("command"),"Saved original command differs");same(caps.process(),process.get("limits"),"Saved supervised process limits differ");
        if(!"completed-process-only".equals(process.get("status"))||NextflowFiles.integer(process.get("exit_code"),0,0)!=0||!NextflowFiles.list(process.get("owned_live_after_cleanup")).isEmpty()||!(producer+"/work").equals(process.get("working_directory"))||!producer.equals(process.get("workspace_root"))||NextflowFiles.list(process.get("owned_processes")).isEmpty())throw new IOException("Original process receipt contradicts a completed supervised run");
        if(process.containsKey("error")||process.containsKey("suppressed"))throw new IOException("Completed original process receipt contains failure diagnostics");
        var launch=NextflowFiles.object(NextflowFiles.json(bundle.resolve("process/launch.json"),16777216));
        for(String key:List.of("command","limits","working_directory","workspace_root","owned_launcher_pid"))same(process.get(key),launch.get(key),"Original launch/final process receipts contradict each other: "+key);
        if(!"running".equals(launch.get("status")))throw new IOException("Original launch receipt lacks its supervised running state");
        var index=NextflowFiles.object(NextflowFiles.json(bundle.resolve("original-files.json"),67108864));var view=view(bundle,index,caps);var outputMembers=new TreeSet<String>();for(Object value:index.values())outputMembers.add(NextflowFiles.text(NextflowFiles.object(value).get("member")));var capturedOutputs=new TreeSet<String>();for(String n:expected.keySet())if(n.startsWith("outputs/"))capturedOutputs.add(n);if(!outputMembers.equals(capturedOutputs))throw new IOException("Complete flat original output inventory differs");
        severe(view,bundle.resolve("process/process.stderr"));Data data=data(bundle,runtime,labels,caps);same(data.document(),report.get("selection"),"Complete saved source-name/descendant/input audit differs");var output=MaltExtractOutputAudit.audit(view,data.populations(),data.names(),modes(profile),!profile.equals("source-default"));same(output,report.get("output_audit"),"Complete saved original statistics/extraction audit differs");
        if(!Files.readString(bundle.resolve("WARNINGS.md"),StandardCharsets.UTF_8).equals(warnings(profile,NextflowFiles.text(report.get("input_provenance")),output)))throw new IOException("Prominent saved warnings differ from recomputed warnings");same(expected,inventory(bundle,caps.fileBytes()),"Complete bundle changed during saved verification");
    }
    private static String warnings(String profile,String provenance,Map<String,Object> output) {
        var w=new StringBuilder("# ORIGINAL MALTEXTRACT1.7 WARNINGS AND REQUIRED ACTIONS\n\n");w.append("**Whole MALT/HOPS qualification and biological paper reproduction remain incomplete. No whole-tool catalog credit is admitted by this development adapter.**\n\nProfile: ").append(profile).append(". Input provenance: ").append(provenance).append(". ");
        w.append(profile.equals("source-default")?"Original destacking, duplicate removal and downsampling remain enabled. Stored populations greater than10000 can be prefix sampled even when the original downSampling? flag is Off.\n\n":"Destacking, duplicate removal and downsampling are explicitly disabled. This deliberate complete profile changes results relative to stock source settings.\n\n");
        for(Object warning:(List<?>)output.get("warnings"))w.append("**").append(warning).append("**\n\n");
        w.append("All original statistics, damage tables, FASTA, BLAST, log and error contents are retained unchanged under flat outputs/ members. original-files.json maps each literal original path to its portable member; no taxon names or nonfinite cells are repaired. Raw original files and process diagnostics also remain outside this portable bundle at the producer. Output statistics are produced by the original program, not reimplemented native statistics. Saved verification checks complete consistency, not authenticity; it does not repeat original execution. Inspect process/process.stderr and the mapped original error.txt/log.txt for all upstream warnings. Sampled process RSS is not a hard aggregate memory bound. An empty candidate set does not establish biological absence or authenticity.\n\n");return w.append(ACTION).append('\n').toString();
    }
